mapper.select:
select t1.REMINDERSTAFFID,t2.CREATEDTIME,t2.REMINDERCONTENT from TBL_SYSTEM_REF_REMINDER_ACCESS t1 inner join TBL_SYSTEM_REF_REMINDER t2 on t2.ID=t1.REMINDERID inner join TBL_SYSTEM_REFOPM_REMINDER t3 on t3.ID=t2.REFOPMID left join TBL_STAFF t4 on t4.STAFFID = t1.REMINDERSTAFFID where t3.CREATOR=#{param.creator} and t3.MODULEROUTE = #{param.moduleRoute}
and t4.REALNAME like concat('%',concat(#{param.reminderStaffName},'%'))
order by t2.id desc
